package android.app;import android.content.*;public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2,FLAG_MUTABLE=4;public Intent intent;public int flags;public boolean foreground;private static PendingIntent make(Intent i,int f,boolean b){PendingIntent p=new PendingIntent();p.intent=i;p.flags=f;p.foreground=b;return p;}public static PendingIntent getActivity(Context c,int n,Intent i,int f){return make(i,f,false);}public static PendingIntent getForegroundService(Context c,int n,Intent i,int f){return make(i,f,true);}}
